// GIVEN — do not change.
class CNode {
    int info;
    CNode next;

    CNode(int x) {
        info = x;
    }
}

public class Josephus {

    static String play(int n, int k) {
        CNode tail = null;
        for (int i = 1; i <= n; i++) {
            CNode q = new CNode(i);
            if (tail == null) {
                q.next = q;
            } else {
                q.next = tail.next;
                tail.next = q;
            }
            tail = q;
        }
        StringBuilder out = new StringBuilder();
        CNode prev = tail; // the node before the person being counted
        while (prev.next != prev) {
            for (int i = 1; i < k; i++) {
                prev = prev.next;
            }
            CNode gone = prev.next;
            out.append(gone.info).append(' ');
            prev.next = gone.next; // O(1) unlink
        }
        return out.toString() + "| survivor " + prev.info;
    }
}

