// GIVEN — do not change.
class Node {
    int info;
    Node next;

    Node(int x) {
        info = x;
    }
}

public class Palin {

    static boolean isPalindrome(Node head) {
        if (head == null || head.next == null) {
            return true;
        }
        Node slow = head;
        Node fast = head;
        while (fast.next != null && fast.next.next != null) { // slow stops at the end of the first half
            slow = slow.next;
            fast = fast.next.next;
        }
        Node second = reverse(slow.next);
        boolean ok = true;
        for (Node a = head, b = second; b != null; a = a.next, b = b.next) {
            if (a.info != b.info) {
                ok = false;
                break;
            }
        }
        slow.next = reverse(second); // put the list back as it was
        return ok;
    }

    private static Node reverse(Node h) {
        Node prev = null;
        while (h != null) {
            Node next = h.next;
            h.next = prev;
            prev = h;
            h = next;
        }
        return prev;
    }
}

