   }
  void deleteFirstMax() {
    if(isEmpty()) return;
    Node m = head, pm = null;          // m = first max node, pm = the node before it
    for(Node p=head, prev=null; p!=null; prev=p, p=p.next)
      if(p.info.price > m.info.price) {m=p;pm=prev;}
    if(pm==null) head=head.next; else pm.next=m.next;
    if(m==tail) tail=pm;
   }

